import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}'),n={name:"guide/quick-start.md"};function o(r,e,d,c,h,l){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Start Deck, inspect existing work, or launch a manual session before deciding whether to connect a repository.</p><h2 id="start-the-dev-servers" tabindex="-1">Start the Dev Servers <a class="header-anchor" href="#start-the-dev-servers" aria-label="Permalink to &quot;Start the Dev Servers&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/dev.sh</span></span></code></pre></div><p>This starts:</p><ul><li><strong>Backend</strong> at <code>http://localhost:8000</code> (API docs at <code>http://localhost:8000/docs</code>)</li><li><strong>Frontend</strong> at <code>http://localhost:5173</code></li></ul><p>Open <code>http://localhost:5173</code> in your browser.</p><p>To stop or restart the dev servers for this checkout:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/dev.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/dev.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div><h2 id="observe-existing-work" tabindex="-1">Observe existing work <a class="header-anchor" href="#observe-existing-work" aria-label="Permalink to &quot;Observe existing work&quot;">​</a></h2><p>Overview is the home page for tracking counts and automation observations across this backend. Use team, scope and harness filters on factory pages; native harness/project preferences do not filter work. Open <a href="/docs/features/work.html">Work</a> for an owner, waiting reason or PR. Open <a href="/docs/features/repositories.html">Repositories</a> to distinguish configured enablement from effective intake. An empty workload does not require enabling autonomy, and a read failure is not an empty factory.</p><h2 id="launch-manually-or-inspect-configuration" tabindex="-1">Launch manually or inspect configuration <a class="header-anchor" href="#launch-manually-or-inspect-configuration" aria-label="Permalink to &quot;Launch manually or inspect configuration&quot;">​</a></h2><p>Use Live sessions for standalone work or <a href="/docs/features/agent-teams.html">Teams</a> for a current launch plan. Reuse only sessions belonging to intended slots. Unbound adoption is an explicit operator review; opening a Work launch link starts nothing.</p><p>Use <a href="/docs/features/harnesses.html">Harnesses</a> for guarded native pages. Local projects scope supported native settings independently of factory filters. Other harnesses&#39; integration capabilities do not create native editors.</p><h2 id="connect-a-backlog-with-the-current-flow" tabindex="-1">Connect a backlog with the current flow <a class="header-anchor" href="#connect-a-backlog-with-the-current-flow" aria-label="Permalink to &quot;Connect a backlog with the current flow&quot;">​</a></h2><p>Open Repositories and select <strong>Set up a repository</strong> for <a href="/docs/features/repositories.html#guided-configuration">guided configuration</a>. It checks access and labels without changes, then saves an inactive team or uses an existing team, with a disabled scope. Launch and activation are separate, reviewed steps. You can also add an existing primary checkout in Teams &gt; Autonomy.</p><p>The Leader is the team&#39;s explicit <code>leader_slot_id</code>. Guided setup names it for a new team; for an existing team, use <strong>Set Leader</strong> in the roster while automation is off. Slot order and Role text do not select it. Configure GitHub polling access on the host and dispatch/design/area labels on GitHub, as described in <a href="/docs/autonomy.html">Autonomous GitHub dispatch</a>. Choose merge policy and finite budgets; review the enable confirmation only when ready.</p><p>The operator credential uses the existing per-tab flow, separately from GitHub polling access and authenticated agent sessions. No cookie login is included. Team/scope pause controls intake; inspect existing attempts separately rather than assuming processes stopped.</p><h2 id="identify-the-backend-instance" tabindex="-1">Identify the Backend Instance <a class="header-anchor" href="#identify-the-backend-instance" aria-label="Permalink to &quot;Identify the Backend Instance&quot;">​</a></h2><p>When you run Claude Deck on more than one machine, or expose it over a LAN or tailnet, set an instance name so each browser window clearly shows the backend it controls:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLAUDE_DECK_INSTANCE_NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Studio Mac&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLAUDE_DECK_INSTANCE_ACCENT=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;blue&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLAUDE_DECK_INSTANCE_ID=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;studio-mac&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">./scripts/dev.sh </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><p>Use a trusted network or tunnel when binding to all interfaces. Protected roster, autonomy and recovery controls require their documented credentials; safe reads remain observational. Local trust is not remote multi-user isolation. A Vite dev UI on another origin needs that exact origin in the JSON <code>CORS_ORIGINS</code> setting; Deck&#39;s production UI is same-origin.</p><p>The instance name appears in the header, browser tab title, Agent Bridge terminal panes, and kill-session confirmations. Supported accents are <code>blue</code>, <code>green</code>, <code>purple</code>, <code>orange</code>, <code>red</code>, <code>pink</code>, <code>cyan</code>, and <code>slate</code>.</p><h2 id="key-pages" tabindex="-1">Key pages <a class="header-anchor" href="#key-pages" aria-label="Permalink to &quot;Key pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/docs/features/dashboard.html">Overview</a></td><td>Tracking counts and automation observations</td></tr><tr><td><a href="/docs/features/work.html">Work</a></td><td>Mixed-team details and current remedies</td></tr><tr><td><a href="/docs/features/repositories.html">Repositories</a></td><td>Watched scopes, intake, polling and overlaps</td></tr><tr><td><a href="/docs/features/harnesses.html">Harnesses</a></td><td>Guarded native settings and manual entry points</td></tr><tr><td><a href="/docs/features/agent-teams.html">Teams</a></td><td>Rosters, launch plans and current repository/autonomy configuration</td></tr><tr><td><a href="/docs/features/agent-bridge.html">Live sessions</a></td><td>Standalone sessions and explicit terminal interaction</td></tr><tr><td><a href="/docs/features/agent-mail.html">Agent Mail</a></td><td>Coordination and read-only work context</td></tr></tbody></table><h2 id="production-build" tabindex="-1">Production Build <a class="header-anchor" href="#production-build" aria-label="Permalink to &quot;Production Build&quot;">​</a></h2><p>To build for production:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/build.sh</span></span></code></pre></div><p>This compiles the app frontend into <code>frontend/dist/</code> and the documentation site into <code>docs/.vitepress/dist/</code>. The backend serves the built app frontend automatically.</p><p>To preview the documentation site while editing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/docs-dev.sh</span></span></code></pre></div><p>Open <code>http://localhost:5174/docs/</code>.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/docs/features/dashboard.html">Features</a> — detailed guides for each feature</li><li><a href="/docs/guide/architecture.html">Architecture</a> — how the app is structured</li><li><a href="/docs/api/">API Reference</a> — REST API documentation</li></ul>`,34)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
